contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint depositAmt, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // need funds to send deposit
        require(address(this).balance >= depositAmt);

        // configure c before initialization so Deposit will log and not be blocked by Initialized
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        // read before-values via public getters
        uint beforeStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractEth = address(c).balance;

        // perform deposit (state-changing top-level call) sending Ether and capture revert status
        bool didRevert;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // read after-values via public getters
        uint afterStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractEth = address(c).balance;

        // Assert the invariant: if Deposit succeeded then both stored balance and contract ETH increased by depositAmt
        assert(didRevert || (afterStored == beforeStored + depositAmt && afterContractEth == beforeContractEth + depositAmt));
    }

    receive() external payable {}
}

