// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt, address logAddr) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.SetLogFile(logAddr) {} catch { return; }
        uint256 beforeStored;
        try c.balances(address(this)) returns (uint256 __r) { beforeStored = __r; } catch { return; }
        uint beforeContractEth = address(c).balance;
        bool didRevert;
        try c.Deposit{value: depositAmt}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterStored;
        try c.balances(address(this)) returns (uint256 __r) { afterStored = __r; } catch { return; }
        uint afterContractEth = address(c).balance;
        assertTrue(didRevert || (afterStored == beforeStored + depositAmt && afterContractEth == beforeContractEth + depositAmt));
    }

    function testFuzz_run(uint256 depositAmt, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(depositAmt, logAddr);
    }

    receive() external payable {}
}
